/**
 * The extended demo media, hosted separately from the npm package.
 *
 * These files are not in the package tarball: download the extended media archive,
 * serve it, and pass its location to `createExtendedDemoAssets()`.
 */
export interface ExtendedDemoAssetDefinitions {
  /** `video/hdr10.webm` (15.4 MB). Singularity, CC-BY-4.0. Load with await `loader.load()`. */
  readonly videoHdr10: { readonly type: 'video'; readonly source: string };
}

/** @internal */
export const buildExtendedDemoAssets = (url: (path: string) => string): ExtendedDemoAssetDefinitions =>
  Object.freeze<ExtendedDemoAssetDefinitions>({
    videoHdr10: { type: 'video', source: url('video/hdr10.webm') },
  });
